/**
 * Adminhtml tax rule Edit Container
 */
namespace Vnecoms\VendorsShippingTableRate\Block\Vendors\Tablerate;

class Edit extends \Vnecoms\Vendors\Block\Vendors\Widget\Form\Container
{

    /**
     * Core registry
     *
     * @var \Magento\Framework\Registry
     */
    protected $_coreRegistry = null;

    /**
     * @param \Magento\Backend\Block\Widget\Context $context
     * @param \Magento\Framework\Registry $registry
     * @param array $data
     */
    public function __construct(
        \Magento\Backend\Block\Widget\Context $context,
        \Magento\Framework\Registry $registry,
        array $data = []
    ) {
        $this->_coreRegistry = $registry;
        parent::__construct($context, $data);
    }

    /**
     * Init class
     *
     * @return void
     */
    protected function _construct()
    {
        $this->_objectId = 'rate_id';
        $this->_controller = 'vendors_tablerate';
        $this->_blockGroup = 'Vnecoms_VendorsShippingTableRate';

        parent::_construct();

        $this->buttonList->update('save', 'label', __('Save Rate'));
        $this->buttonList->update('delete', 'label', __('Delete Rate'));

        $this->buttonList->add(
            'save_and_continue',
            [
                'label' => __('Save and Continue Edit'),
                'class' => 'save',
                'data_attribute' => [
                    'mage-init' => ['button' => ['event' => 'saveAndContinueEdit', 'target' => '#edit_form']],
                ]
            ],
            10
        );
    }
}
